import math

def dpo_pair_loss(r_chosen: float, r_rejected: float) -> float:
    margin = r_chosen - r_rejected
    prob = 1 / (1 + math.exp(-margin))
    return round(-math.log(prob), 4)

def dpo_batch_loss(pairs: list) -> float:
    """Average DPO loss across a batch of (r_chosen, r_rejected) pairs."""
    losses = [dpo_pair_loss(c, r) for c, r in pairs]
    return round(sum(losses) / len(losses), 4)

print(dpo_batch_loss([(0.27, -0.27), (0.05, 0.4), (0.9, -0.2)]))
